package com.nigson.experience.distributor;

import com.nigson.experience.platform.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.*;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import static org.assertj.core.api.Assertions.*;

class DistributorPersistenceTest {
 private JdbcTemplate jdbc;private DistributorService service;private StatefulDistributorEntitlementMock commerce;private DataSourceTransactionManager manager;private final Clock clock=Clock.systemUTC();private final UUID applicant=UUID.randomUUID(),market=UUID.randomUUID(),book=UUID.randomUUID();private PrivateWorkload.Proof proof(String api,UUID party,String role,String scope){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals(api)).findFirst().orElseThrow();var actor=new ActorAssertion.Actor(party,"https://identity.synthetic.invalid","synthetic-user",null,Set.of(role),Set.of(scope),null);return new PrivateWorkload.Proof(route.client(),"synthetic-workload",route,actor);}
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"native distributor PostgreSQL harness supplies database");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=experience","nigson_experience_app","mock-experience-runtime");jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);var metrics=new SimpleMeterRegistry();commerce=new StatefulDistributorEntitlementMock();service=new DistributorService(jdbc,new PlatformStore(jdbc,manager,clock,metrics),new AuditWriter(jdbc,clock,metrics),clock,Set.of("CERTIFICATE","IDENTITY"),"synthetic-distributor-review",commerce);}
 private UUID file(UUID owner,String scan){UUID id=EventCodec.uuid7(clock.instant());jdbc.update("INSERT INTO experience.file_asset(id,created_by,updated_by,owner_party_id,object_key,purpose,mime_type,byte_size,checksum_sha256,classification,scan_status) VALUES (?,'test','test',?,?,'DISTRIBUTOR_PROOF','application/pdf',2048,?,'PRIVATE',?)",id,owner,"distributor-test/"+id,"a".repeat(64),scan);return id;}
 private DistributorValues.Application submit(UUID party){var p=proof("API-092",party,"CUSTOMER","distributor.create_WITH_SIGNED_CUSTOMER");var docs=List.of(new DistributorValues.Document(file(party,"CLEAN"),""),new DistributorValues.Document(file(party,"CLEAN"),""));return service.submit(p,new DistributorValues.Submission("Synthetic Distributor","NG","SYN-"+UUID.randomUUID(),docs),UUID.randomUUID().toString(),UUID.randomUUID());}
 @Test void applicantOwnershipCleanPrivateFilesReviewTwoActorsAndAcknowledgedActivationSuspension(){var app=submit(applicant);assertThat(app.state()).isEqualTo("SUBMITTED");assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='distributor.application.created.v1'",Long.class,app.id())).isEqualTo(1);String event=jdbc.queryForObject("SELECT payload::text FROM experience.outbox_event WHERE aggregate_id=? AND event_type='distributor.application.created.v1'",String.class,app.id());assertThat(EventCodec.decode(event).path("payload").path("recipient_group").asString()).isEqualTo("synthetic-distributor-review");assertThat(service.mine(proof("API-093",applicant,"CUSTOMER","distributor.read_WITH_SIGNED_CUSTOMER"))).extracting(DistributorValues.Application::id).containsExactly(app.id());assertThatThrownBy(()->service.review(proof("API-172",applicant,"CUSTOMER","distributor.review_WITH_SIGNED_ACTOR"),app.id(),"Checked proofs",true,0,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);
  UUID reviewer=UUID.randomUUID(),decisionActor=UUID.randomUUID();var reviewed=service.review(proof("API-172",reviewer,"SALES","distributor.review_WITH_SIGNED_ACTOR"),app.id(),"Verified applicant documents",true,0,UUID.randomUUID().toString(),UUID.randomUUID());assertThat(reviewed.state()).isEqualTo("UNDER_REVIEW");String approveKey=UUID.randomUUID().toString();var approved=service.decide(proof("API-095",decisionActor,"SALES","distributor.decision_WITH_SIGNED_ACTOR"),app.id(),new DistributorValues.Decision("APPROVE","Approved after independent review",market,book),approveKey,1,UUID.randomUUID());assertThat(approved.state()).isEqualTo("APPROVED");assertThat(approved.organizationId()).isNotNull();assertThat(jdbc.queryForObject("SELECT acknowledgment_revision FROM experience.distributor_application WHERE id=?",Long.class,app.id())).isZero();var suspended=service.decide(proof("API-095",UUID.randomUUID(),"SALES","distributor.decision_WITH_SIGNED_ACTOR"),app.id(),new DistributorValues.Decision("SUSPEND","Current compliance review",null,null),UUID.randomUUID().toString(),3,UUID.randomUUID());assertThat(suspended.state()).isEqualTo("SUSPENDED");assertThat(jdbc.queryForObject("SELECT acknowledgment_revision FROM experience.distributor_application WHERE id=?",Long.class,app.id())).isEqualTo(1);assertThat(commerce.acceptedCommandCount()).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM experience.outbox_event WHERE aggregate_id=? AND event_type='distributor.decision.requested.v1'",Long.class,app.id())).isEqualTo(2);var detail=service.detail(proof("API-177",UUID.randomUUID(),"SALES","distributor.detail_WITH_SIGNED_ACTOR"),app.id());assertThat(detail.state()).isEqualTo("SUSPENDED");assertThat(detail.documents()).hasSize(2);}
 @Test void rejectedFilesAndApplicantOwnershipAreDeniedAndRejectNeverCallsCommerce(){UUID other=UUID.randomUUID();var wrong=new DistributorValues.Submission("Synthetic","NG",null,List.of(new DistributorValues.Document(file(other,"CLEAN"),""),new DistributorValues.Document(file(other,"CLEAN"),"")));assertThatThrownBy(()->service.submit(proof("API-092",applicant,"CUSTOMER","distributor.create_WITH_SIGNED_CUSTOMER"),wrong,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);var dirty=new DistributorValues.Submission("Synthetic","NG",null,List.of(new DistributorValues.Document(file(applicant,"QUARANTINED"),""),new DistributorValues.Document(file(applicant,"CLEAN"),"")));assertThatThrownBy(()->service.submit(proof("API-092",applicant,"CUSTOMER","distributor.create_WITH_SIGNED_CUSTOMER"),dirty,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class);var app=submit(applicant);var rejected=service.decide(proof("API-095",UUID.randomUUID(),"SALES","distributor.decision_WITH_SIGNED_ACTOR"),app.id(),new DistributorValues.Decision("REJECT","Incomplete commercial evidence",null,null),UUID.randomUUID().toString(),0,UUID.randomUUID());assertThat(rejected.state()).isEqualTo("REJECTED");assertThat(commerce.acceptedCommandCount()).isZero();}
 @Test void uncertainAcceptedCommerceCommandRetriesSameCommandAndStaleVersionsFail(){var app=submit(applicant);var reviewer=proof("API-172",UUID.randomUUID(),"SALES","distributor.review_WITH_SIGNED_ACTOR");service.review(reviewer,app.id(),"Proofs checked",true,0,UUID.randomUUID().toString(),UUID.randomUUID());var actor=proof("API-095",UUID.randomUUID(),"SALES","distributor.decision_WITH_SIGNED_ACTOR");String key=UUID.randomUUID().toString();var approve=new DistributorValues.Decision("APPROVE","Approved independently",market,book);commerce.timeoutAfterNextAcceptance();assertThatThrownBy(()->service.decide(actor,app.id(),approve,key,1,UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(x->((Problem.Failure)x).code).isEqualTo(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);assertThat(jdbc.queryForObject("SELECT status FROM experience.distributor_application WHERE id=?",String.class,app.id())).isEqualTo("ACTIVATION_PENDING");commerce.returnOutOfOrderAcknowledgmentNext();assertThatThrownBy(()->service.decide(actor,app.id(),approve,key,1,UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(x->((Problem.Failure)x).code).isEqualTo(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);assertThat(jdbc.queryForObject("SELECT status FROM experience.distributor_application WHERE id=?",String.class,app.id())).isEqualTo("ACTIVATION_PENDING");var recovered=service.decide(actor,app.id(),approve,key,1,UUID.randomUUID());assertThat(recovered.state()).isEqualTo("APPROVED");assertThat(commerce.acceptedCommandCount()).isEqualTo(1);assertThatThrownBy(()->service.review(reviewer,app.id(),"Stale review",true,0,UUID.randomUUID().toString(),UUID.randomUUID())).isInstanceOf(Problem.Failure.class).extracting(x->((Problem.Failure)x).code).isEqualTo(ProblemCode.VERSION_MISMATCH);assertThat(service.decide(actor,app.id(),approve,key,1,UUID.randomUUID())).isEqualTo(recovered);}
}
